do $scaffold$
declare p jsonb;l jsonb;s jsonb;c jsonb;i jsonb; pid uuid;lid uuid;sid uuid;cid uuid; targetseq integer;t text;d text;before_progress jsonb:='{}';after_progress jsonb:='{}';existing record;
begin
 foreach t in array array['student_curriculum_enrollments','student_level_progress','student_subject_progress','student_component_progress','student_component_item_progress'] loop
  execute format('select md5(coalesce(jsonb_agg(to_jsonb(x) order by id)::text,''[]'')) from public.%I x',t) into d;before_progress:=before_progress||jsonb_build_object(t,d);
 end loop;
 for p in select value from jsonb_array_elements((select payload from release_scaffold_plan)) loop
  select id into pid from public.curriculums where code=p->'row'->>'code';
  if pid is null then
   if exists(select 1 from public.curriculums where lower(trim(name))=lower(p->'row'->>'name')) then raise exception 'RELEASE_PROGRAM_IDENTITY_CONFLICT';end if;
   insert into public.curriculums(code,name,description,status) values(p->'row'->>'code',p->'row'->>'name',p->'row'->>'description',p->'row'->>'status') returning id into pid;
  end if;
  for l in select value from jsonb_array_elements(p->'levels') loop
   select id into lid from public.curriculum_levels where curriculum_id=pid and code=l->'row'->>'code';
   if lid is not null then continue;end if;
   if exists(select 1 from public.curriculum_levels where curriculum_id=pid and lower(trim(name))=lower(l->'row'->>'name')) then raise exception 'RELEASE_LEVEL_IDENTITY_CONFLICT';end if;
   targetseq:=(l->'row'->>'sequence_no')::int;
   for existing in select id,sequence_no from public.curriculum_levels where curriculum_id=pid and sequence_no>=targetseq order by sequence_no desc loop
    update public.curriculum_levels set sequence_no=existing.sequence_no+1 where id=existing.id;
   end loop;
   insert into public.curriculum_levels(curriculum_id,code,name,sequence_no,level_number,level_type,completion_rule,status) values(pid,l->'row'->>'code',l->'row'->>'name',targetseq,(l->'row'->>'level_number')::int,l->'row'->>'level_type',l->'row'->>'completion_rule',l->'row'->>'status') returning id into lid;
   for s in select value from jsonb_array_elements(l->'subjects') loop
    insert into public.curriculum_subjects(level_id,code,name,family_code,subject_level,sort_order,status,is_required,completion_rule) values(lid,s->'row'->>'code',s->'row'->>'name',s->'row'->>'family_code',(s->'row'->>'subject_level')::int,(s->'row'->>'sort_order')::int,s->'row'->>'status',(s->'row'->>'is_required')::boolean,s->'row'->>'completion_rule') returning id into sid;
    for c in select value from jsonb_array_elements(s->'components') loop
     insert into public.curriculum_subject_components(subject_id,code,name,sort_order,status,is_required,completion_rule) values(sid,c->'row'->>'code',c->'row'->>'name',(c->'row'->>'sort_order')::int,c->'row'->>'status',(c->'row'->>'is_required')::boolean,c->'row'->>'completion_rule') returning id into cid;
     for i in select value from jsonb_array_elements(c->'items') loop
      insert into public.curriculum_component_items(component_id,code,name,sort_order,status,is_required) values(cid,i->>'code',i->>'name',(i->>'sort_order')::int,i->>'status',(i->>'is_required')::boolean);
     end loop;
    end loop;
   end loop;
  end loop;
 end loop;
 foreach t in array array['student_curriculum_enrollments','student_level_progress','student_subject_progress','student_component_progress','student_component_item_progress'] loop
  execute format('select md5(coalesce(jsonb_agg(to_jsonb(x) order by id)::text,''[]'')) from public.%I x',t) into d;after_progress:=after_progress||jsonb_build_object(t,d);
 end loop;
 if after_progress is distinct from before_progress then raise exception 'RELEASE_STUDENT_PROGRESS_CHANGED';end if;
 -- Reuse the legacy Drum identity required by the canonical DRUMS filter.
 -- IDs and all existing branch/student/audit references remain intact.
 if not exists(select 1 from public.curriculums where code='DRUMS') and exists(select 1 from public.curriculums where code='DRUM') then
  if (select count(*) from public.curriculums where code in('DRUM','DRUMS') or lower(trim(name)) in('drum','drums','trống')) <> 1 then raise exception 'RELEASE_DRUM_IDENTITY_AMBIGUOUS';end if;
  update public.curriculums set code='DRUMS',name='Trống' where code='DRUM';
 end if;

end $scaffold$;
